mapper.insert:
		/*
             SQL ID : SrvyPtcpHstryDAO.srvyPtcpHstryRegist
             설  명  : 설문참여이력등록
         */
        INSERT INTO TB_LMS_SRVY_PTCP_HSTRY (
        	  SRVY_PTCP_HSTRY_ID
			, USER_ID
			, SRVY_ID
			, SRVY_HSTRY_GBNCD
			, PTCP_SDTTM
			, PTCP_EDTTM
			, CNTN_IP
			, RGTR_ID
			, REG_DTTM
        ) VALUES (
        	  #{srvyPtcpHstryId}
			, #{userId}
			, #{srvyId}
			, #{srvyHstryGbncd}
			, NVL(#{ptcpSdttm}, FN_DTTM())
			, #{ptcpEdttm}
			, #{cntnIp}
			, #{rgtrId}
			, FN_DTTM()
        )
